ROOT=Path(__file__).resolve().parents[1]
slides=[]
def add(title,typ='columns',lead='',items=None,takeaway='',pages='',notes='',**kw):
    s=dict(title=title,type=typ,lead=lead,source='教材第三章 '+pages if pages else '教学设计 / 校园咖啡店模拟',notes=notes)
    if items is not None:s['items']=items
    if takeaway:s['takeaway']=takeaway
    s.update(kw);slides.append(s)
def chart(title,series,xlabel,ylabel,items,**kw):add(title,'chart',items=items,series=series,xlabel=xlabel,ylabel=ylabel,**kw)
def table(title,headers,rows,**kw):add(title,'table',headers=headers,rows=rows,**kw)
add('风险型决策分析','cover',notes='第三章8学时，四次90分钟。先作判断，再计算；每次课保留讨论、解释和独立退出题。金额均为教学或教材情境，不是现实投资建议。')
add('如果客流不确定，还敢开大店吗？',lead='先投票：不投资、小店、大店；写出你的依据。',items=[['小店','高客流净价值 8 万元\n低客流净价值 2 万元\n投入较稳，收益上限较低'],['大店','高客流净价值 16 万元\n低客流净价值 −6 万元\n可能赚得更多，也可能亏损']],takeaway='“大店收益最高”和“大店最值得选”之间，还缺少哪些信息？',notes='第三章新增模拟情境：表中为同一研究期、同一折现率下的全期净现值，已扣投资和经营成本。并非第二章现金流直接变换得到。不能再次扣初始投入或再次折现。')
add('四次课，逐步打开信息',items=[['前半程 · 两次 90 分钟','① 概率、期望值与损失\n② 决策树与后续行动\n每一步先预测，再验证'],['后半程 · 两次 90 分钟','③ 贝叶斯、调查与抽样\n④ 敏感性、效用与项目质询\n最后提交可复算的 M3']],takeaway='会算最优值，也要解释信息何时可用、结论何时改变。',notes='推荐主讲53页，附录用于分层练习。第1课页1—14，第2课15—24，第3课25—38，第4课39—53。完整时间安排见教师指南。')
add('风险型：结果未知，概率可描述',pages='§1，p.50—51',items=[['五个建模条件','明确目标；存在可选方案\n存在不可控的自然状态\n能算各结果；能估计状态概率'],['概率不是承诺','状态互斥且穷尽，概率和为 1\n概率来自数据或明确判断\n不确定型缺少可信的概率描述']],takeaway='风险的概率与后果都要描述；R=f(C,P) 不是一条通用乘法公式。',notes='请学生指出可控制的店面规模与不可控制的客流；概率已知是模型前提，不等于现实中永不改变。资金、产能等约束仍先检查。')
table('把故事压缩成一张损益表',['方案 / 万元','高客流，p=0.6','低客流，1−p=0.4'],[['不投资','0','0'],['小店','8','2'],['大店','16','−6']],takeaway='表中是已经折现到同一时点的净价值；决策发生在客流揭晓之前。',notes='主线数据独立于第二章设备数据，均为教学模拟。不投资也是行动；0表示相对于现状没有增量价值。')
add('期望值：对可能结果加权','equations',pages='§1，p.51—52',items=[['对每个可行方案求和','EMV(a) = Σ p(θ) × V(a,θ)','小店：0.6×8 + 0.4×2 = 5.6 万元'],['用同一准则比较','大店：0.6×16 + 0.4×(−6) = 7.2 万元','风险中性、无额外约束时，选大店']],takeaway='收益取最大；若表中是成本，目标和比较方向都要一致。',notes='权重只加在状态，不给行动分配自然概率。7.2并不是某一个实际结果，单次只会得到16或−6。')
chart('同一模型，期望值与结果分开看',[{'name':'小店','points':[[0,2],[1,8]]},{'name':'大店','points':[[0,-6],[1,16]]}], '状态编码：0 低客流 / 1 高客流','净价值 / 万元',[['大店的代价','期望 7.2；亏损概率 40%\n一次经营可能得到 −6'],['小店的特征','期望 5.6；此模型中不亏损\n但上行收益较低']],chartmode='stem',takeaway='期望值更大，不代表每种状态都更好。',pages='§1，p.50—54',notes='状态编码只是类别位置，不能把0.5解释为第三个客流状态。图以离散竖线表示两种结果。网页可改损益，显示标准差和亏损概率。')
add('C3-E1：让同一个模型经历很多次','activity',items=[['先猜一次','高客流概率 0.6，大店这一次会得到 7.2 吗？'],['再看很多次','网页固定种子 2026，分别运行 10、100、1000 次独立抽样。'],['解释曲线','记录样本均值与理论期望；换种子后，路径是否仍相同？']],takeaway='独立、同分布与有限期望支撑长期平均解释；一次大项目不能自动复制。',notes='模拟是检查模型行为，不是用随机输出证明概率假设正确。共享状态样本便于比较方案。样本均值不保证单调逼近期望。')
table('教材核验：扩建规模如何选？',['规模','畅销 / 滞销，万元','EMV（p=0.7）'],[['大规模','200 / −60','122'],['中规模','150 / 20','111'],['小规模','100 / 60','88']],pages='例 3-1，p.51—52',takeaway='先检验收益表，再求每行加权平均；不能用每行的最大值替代。',notes='小规模最坏结果更好，大规模EMV更高。相应推荐依赖风险中性和可承受损失的条件。')
add('机会损失：知道答案以后差了多少？','equations',pages='§1，p.54—55',items=[['按每个状态找到事后最好结果','L(a,θ) = max V(·,θ) − V(a,θ)','大店的后悔值：高客流 0，低客流 8'],['再按事前概率加权','EOL(大店) = 0.6×0 + 0.4×8 = 3.2','同一损益表：最小 EOL 与最大 EMV 选出相同方案']],takeaway='机会损失是相对于事后最好选择的差额，不等于账面亏损。',notes='不投资在低客流没有实际亏损，却仍有2万元机会损失。此处有概率，不是第四章最大后悔值最小准则。')
add('完全信息，最多值多少钱？','equations',pages='§1，p.54—55',items=[['若先知道客流，再选规模','EVwPI = 0.6×16 + 0.4×2 = 10.4','现在不知道客流：最大 EMV = 7.2'],['完全信息价值','EVPI = EVwPI − max EMV = 3.2 万元','也等于最小期望机会损失 3.2 万元']],takeaway='3.2 是此模型中完全信息的期望价值上限，不是任何调查的合理价格。',notes='两个顺序不同：平均之后取最大、每个状态先取最大再平均。信息必须在不可逆决策之前到达且可以用于行动。')
chart('信息的价值来自改变行动',[{'name':'先决定规模','points':[[0,2],[25,2.0],[50,5],[75,10.5],[100,16]]},{'name':'先知道客流','points':[[0,2],[25,5.5],[50,9],[75,12.5],[100,16]]}], '高客流概率 / %','最优期望净价值 / 万元',[['两条线之间','完全信息的价值 EVPI\n概率在 0 或 1 时为 0'],['切换点 p=0.5','小店与大店 EMV 相等\n此处完全信息价值为 4']],takeaway='无信息曲线应取各行动期望值的上包络。',notes='图的25%点应为小店3.5万元；由生成脚本末尾统一公式重算，避免手录示意值。p=0时小店2，大店−6；p=1时大店16。')
add('教材的“离差”不是标准差',pages='§1，例 3-3，p.53—54',items=[['教材的辅助指标','“离差” = EMV − 最坏结果\n用于期望值相等时的辅助比较\n例中 d₂ 与 d₃ 的 EMV 都是 28'],['统计学的标准差','SD = √Σp(结果−EMV)²\n描述结果围绕均值的波动\n不能与教材“离差”混用']],takeaway='d₃ 的教材离差应为 28−21=7；表中 8 与正文不一致。',notes='网页标准差明确标为SD。该辅助规则不代表完整风险偏好模型；有资金约束时先筛除不可承受方案。')
add('第 1 课退出题','activity',items=[['计算','大店仍为 16 / −6，高客流概率变成 0.4，EMV 是多少？'],['辨析','某方案没有负收益，它的期望机会损失是否一定为 0？'],['解释','完全信息到达时店已经建好，前面的 EVPI 还能直接兑现吗？']],takeaway='参考：2.8 万元；不一定；不能，信息的可行动时点改变了。',notes='个人先答3分钟，邻座互查2分钟。把“公式正确但时间顺序错误”的答案留到第二课修正。')
add('决策树：把时间顺序画出来','flow',pages='§2，p.55—56',steps=['现在选择','观察信息','再作选择','结果兑现'],details=['方框：由你控制','圆圈：自然或报告','方框：可调整行动','终端：同口径净值'],takeaway='先后关系决定能用什么信息；不能让早期决策偷看未来结果。',notes='决策树不只是把表格换一种画法。多期自然状态不自动意味着多次决策，要确有后续行动选项。')
add('圆圈求平均，方框取最优','tree',pages='§2，p.55—60',takeaway='从右向左回溯；在方框删去较差行动，不删掉不喜欢的随机分支。',notes='本图使用咖啡店基础例。根节点选择小店或大店，圆圈分别按0.6/0.4加权。叶节点数值已经是净价值，不能再扣一次投入。')
add('复杂的树，也只重复两种运算','flow',pages='§2，p.55—60',steps=['写终端值','折回圆圈','折回方框','回到现在'],details=['统一时点与单位','Σ 条件概率×后续值','取可行行动最大值','保留完整条件策略'],takeaway='“若观察到 H，就选择 a(H)”是一条策略，比单个方案更完整。',notes='如效用模型，终端先转换为效用，随后同样进行期望和比较；不能把货币和效用混在同一节点。')
table('例 3-8：先建中店，还是小店再扩？',['条件','中店','小店'],[['期初投资 / 万元','400','150'],['前 3 年：好 / 差，年收益','100 / 10','60 / 2'],['后 7 年：好 / 差，年收益','150 / 10','60 / 2；扩后 150 / 10'],['第 3 年后可选行动','保持','前期好时，可付 210 扩建']],pages='例 3-8，p.59—60',takeaway='沿用教材不折现的简化；这里的年收益要乘年数，再扣对应投资。',notes='第一阶段好概率0.75。后期好条件概率：若前期好为0.85；若前期差为0.1。只有小店且前期好才能扩建。金额为万元。')
add('先算最晚的选择','equations',pages='例 3-8，p.59—60',items=[['小店且前期好：扩建还是保持？','扩建：7×(0.85×150+0.15×10)−210 = 693','保持：7×(0.85×60+0.15×2) = 359.1'],['小店且前期差：按教材保持','后 7 年：7×(0.1×60+0.9×2) = 54.6','因此“先小店”的策略是：好则扩，差则保持']],takeaway='未来节点上的选择，必须先算好，才能回到期初比较。',notes='不要把后7年的0.85当成无条件概率。小店好分支选择扩建，并不说明根节点就应选择小店。')
add('再回到现在比较完整策略','equations',pages='例 3-8，p.59—60',items=[['先建小店，随后按情况行动','3×(0.75×60+0.25×2)+0.75×693+0.25×54.6−150','= 519.90 万元'],['先建中店','前 3 年收益 + 后 7 年条件期望收益 − 400','= 551.75 万元；期初选中店']],takeaway='最优子策略可以存在于根节点最终未选的分支上。',notes='中店后7年两个条件值为903和168，前3年期望232.5；总值232.5+.75×903+.25×168−400=551.75。')
chart('扩建费变了，哪一层先改变？',[{'name':'先建中店','points':[[x,551.75] for x in range(0,701,10)]},{'name':'先建小店并优化后续','points':[[x,136.5+.75*max(903-x,359.1)+.25*54.6-150] for x in range(0,701,10)]}],'扩建费 / 万元','期初最优策略值 / 万元',[['约 167.53','期初中店与小店策略相等'],['543.90','前期好时，扩建与保持相等\n这是另一个节点的阈值']],takeaway='参数可能先改变期初选择，之后才改变某个后续行动。',pages='例 3-8 的参数实验',notes='两个阈值分别解677.4−.75C=551.75和903−C=359.1。C>543.9后小店价值不再下降，因为可放弃扩建。')
add('C3-E2：一步一步揭开回溯','activity',items=[['遮住答案','网页只显示条件和终端；先写后期两个候选值。'],['分步揭示','依次显示后期条件期望、扩建选择、期初选择。'],['现场改参','将扩建费设为 100、210、600，解释两层决策的变化。']],takeaway='提交一条包含“如果……就……”的策略，并标出信息可用时点。',notes='默认210：根节点中店；100：根节点小店且好时扩；600：小店好时也保持，但期初仍中店。')
add('树上最容易出现的三种错误','activity',pages='§2，p.55—60',items=[['把概率放错','P(后期好 | 前期好)=0.85，不是所有路径的概率。'],['把费用扣两次','若终端已含投资，就不再在根节点扣；画出费用时点。'],['把未来当已知','只有观察到报告之后，才允许按报告选择行动。']],takeaway='检查每个圆圈的分支概率和为 1，并检查完整路径的概率乘积。',notes='多阶段模型若加入折现，先统一节点价值时点，跨期回溯需要折现；教材本例没有这样处理。')
add('第 2 课退出题','activity',items=[['识别','市场调查是一个行动，调查报告是什么节点？'],['计算','好报告概率 0.4，对应最优值 10；差报告值 2，平均多少？'],['解释','为什么不能用 max(10,2)=10 作为调查方案的价值？']],takeaway='参考：报告是机会节点；5.2；你能选择是否调查，却不能选择报告内容。',notes='下一课加入报告不完全可靠的问题。调查的固定成本还需从5.2中扣除，前提是两个后续值尚未扣它。')
add('调查说“好”，真好概率就是 80%？',pages='§3，p.60—62',items=[['调查的可靠性','P(好报告 | 高客流)=0.8\nP(好报告 | 低客流)=0.2\n这是似然，不是后验'],['决策真正需要的','P(高客流 | 好报告)=？\n还需要高客流的先验概率\n基础发生率不能省略']],takeaway='P(H|θ) 与 P(θ|H) 的条件方向相反。',notes='先让学生投票80%、85.7%、无法算。给出先验0.6后可计算6/7。混淆似然与后验是本节核心纠错。')
table('想象 1000 个同类情境',['自然状态','好报告','差报告'],[['高客流：600','480','120'],['低客流：400','80','320'],['合计','560','440']],takeaway='好报告中的高客流比例：480 / 560 = 85.71%。',notes='这些是由概率推出的期望频数，不是真实抽样观测。先在所有高客流中数好报告，再切换到好报告这一列。')
add('贝叶斯公式：先联合，再归一','equations',pages='§3，p.61—62',items=[['联合概率与报告概率','P(θ,H)=P(θ)P(H|θ)','P(H)=Σ P(θ)P(H|θ)'],['后验概率','P(θ|H)=P(θ)P(H|θ) / P(H)，要求 P(H)>0','P(高|好)=0.48/0.56=6/7；P(高|差)=0.12/0.44=3/11']],takeaway='不可能出现的报告 P(H)=0，不定义后验，也不贡献事前价值。',notes='网页对不可能报告显示“不会出现”，不产生NaN，也不虚构均匀后验。')
table('报告之后，重新比较每个行动',['报告','小店 EMV / 万元','大店 EMV / 万元'],[['好报告，概率 0.56','7.1429','12.8571 → 选大店'],['差报告，概率 0.44','3.6364 → 选小店','0.0000']],takeaway='调查的作用：把固定行动变成“好则大、差则小”的策略。',notes='差报告大店刚好0，小店36/11。所有数值由未舍入后验算出；不把显示的四位小数用于后续连乘。')
add('调查前，先算“未来会怎样用它”','flow',pages='§3，p.62—65',steps=['先验分析','预后验分析','后验分析','序贯分析'],details=['现在没有新资料','枚举报告及最佳行动','观察实际报告后更新','继续收集，重复更新'],takeaway='预后验分析发生在调查之前：评价的是一项信息方案。',notes='四阶段不是四种互斥公式。序贯分析允许每轮根据新信息决定继续还是停止，本章先建立基本思想，第六章再系统展开。')
add('不完全信息价值 EVSI','equations',pages='§3，p.65—68',items=[['有调查，但尚未扣调查费','EVwSI = 0.56×12.857142… + 0.44×3.636363… = 8.8','EVSI = 8.8 − 7.2 = 1.6 万元'],['调查成本 0.5 万元','调查后净价值 = 8.8 − 0.5 = 8.3','相对不调查的净改善 = 1.6 − 0.5 = 1.1']],takeaway='EVSI（教材亦称 EVAI）是信息毛价值；净改善还要减调查费一次。',notes='EVPI=3.2，因此0≤1.6≤3.2。支付成本只发生在选调查时；不调查的基准不扣它。')
chart('调查越来越贵，何时不值得买？',[{'name':'调查后净价值','points':[[x/10,8.8-x/10] for x in range(31)]},{'name':'不调查','points':[[0,7.2],[3,7.2]]}],'调查费 / 万元','期望净价值 / 万元',[['保留价格 1.6','费用低于 EVSI 时值得调查\n相等时两者并列'],['价值上限 3.2','EVPI 是完全信息的上限\n不能拿它替代此调查的 1.6']],takeaway='信息成本不改变本模型的后验概率，但改变是否购买信息的选择。',notes='本页用风险中性货币评价，且调查只改变信息，不改变客流或可行行动集。')
add('信息为什么可能毫无价值？',pages='§3，p.65—68',items=[['没有信息量','好报告在高低客流下同样常见\n后验等于先验\nEVSI = 0'],['有信息却不改行动','后验发生变化\n但每种报告后仍选同一方案\n风险中性模型中 EVSI 仍可为 0']],takeaway='信息是可忽略的，所以毛价值非负；付费调查的净改善却可能为负。',notes='如果信息改变约束或本身造成成本/伤害，需扩展模型，不能直接套免费的可忽略信息定理。网页敏感度=0.5、特异度=0.5是无信息预设。')
add('C3-E3：从概率到行动的完整链','activity',items=[['基准复算','p=0.6、敏感度=0.8、特异度=0.8、费用=0.5。'],['极端检验','完全准确、完全无信息、某报告不可能发生，各试一次。'],['作出建议','写明调查前的选择、报告后的策略，以及最高愿付费用。']],takeaway='交付后验表与净改善；“准确率很高”不能替代信息价值计算。',notes='准确率不是单独充分参数；至少说明各状态下报告的条件概率。网页默认与课件同源数值。')
table('教材例 3-10：避免被坏消息误导',['项目','精确复算结果'],[['无调查；先验成功 0.8','生产 EMV = 11 000 元'],['预测好 / 预测差','概率 0.78 / 0.22；后验 0.97436 / 0.18182'],['有报告后的策略','好则生产，差则不生产；毛价值 11 300 元'],['信息价值','EVSI = 300 元；EVPI = 1 000 元']],pages='例 3-10，p.65—68',takeaway='坏消息降低项目估值，不代表这条信息在决策上造成了损失。',notes='生产成功15000，失败−5000；好报告给定成功.95，给定失败.1。分报告信息增益应比较同一后验下“新策略”与“原策略”；不是把所有坏消息价值当负数。')
add('抽样：每多看一件，都值得吗？',pages='例 3-11，p.69—71',items=[['采购一箱商品','缺陷率 θ：0.20、0.10、0.05\n先验：0.50、0.30、0.20\n购买净收益：−5、5、10 元'],['用样本更新','有放回抽取 n 件，观察缺陷数 X\nX|θ 服从二项分布\n按每个 X 决定买或不买']],takeaway='样本量影响信息价值；固定费与逐件费用影响最优样本量。',notes='沿用教材一箱100件、购价85、完好价值100的简化；抽样可放回且不影响可售数量。现实破坏性检验必须加入消耗成本与抽样机制变化。')
add('四件都合格，才购买','equations',pages='例 3-11，p.69—71',items=[['n=4，X=0','P(X=0)=0.5×0.8⁴+0.3×0.9⁴+0.2×0.95⁴=0.56453125','该报告对最优毛价值的贡献 = 1.5891625 元'],['四件中发现任何缺陷，选择不买','先验直接买的期望 = 1 元','EVSI(4)=1.5891625−1=0.5891625 元']],takeaway='0.58916 是四件样本的信息毛价值；不等于每件样本都值这么多。',notes='X=0条件下购买期望=1.5891625/.56453125≈2.8150，其他报告下买的期望为负。程序枚举X=0…4，并显示后验与行动。')
add('最优样本量：把“不抽样”也放进去','equations',pages='§3，p.70—71',items=[['对每个候选 n 重新计算信息价值','净改善(n)=EVSI(n)−C(n)','C(0)=0；n>0 时 C(n)=固定费+n×单件费用'],['比较全部候选','n* ∈ argmax 净改善(n)，必须包括 n=0','网页枚举 n=0…40；若最优落在 40，应检查更大范围']],takeaway='不能把某个固定 n 的 EVSI，当成所有样本量都不变的常数。',notes='有限枚举只保证给定范围最优，不宣称全局无界样本量最优。网页显示所有并列最优，零单价零固定费用是有用边界测试。')
add('第 3 课退出题','activity',items=[['概率方向','调查“发现好市场”的概率，等于“报告好后市场好”的概率吗？'],['价值边界','某计算得到 EVSI=4、EVPI=3，应该先检查什么？'],['成本与策略','调查后每份报告都选大店，信息毛价值能为正吗？']],takeaway='参考：不同；检查概率、信息时点、行动集合及费用口径；在本章条件下不能。',notes='先给概念解释，再让学生用网页无信息预设举例。不要把成本扣入EVSI而导致负毛价值。')
add('敏感性：概率估错多少会改变选择？','equations',pages='§4，p.74—75',items=[['咖啡店两条期望直线','EMV(小店)=2+6p；EMV(大店)=−6+22p','令二者相等：p*=0.5'],['结论要附条件','p<0.5 选小店；p>0.5 选大店；p=0.5 并列','如果可信概率区间跨过 0.5，应优先改善估计']],takeaway='敏感性回答“何时翻转”；不会替你证明概率估计正确。',notes='如自定义损益，需把不投资一并比较。两两交点只有在上包络上才是最优方案的切换点。')
