add('教材例 3-12：0.65 是近似值','equations',pages='例 3-12，p.74—75',items=[['市场不变概率为 p','甲：50p−20(1−p)；乙：−15p+100(1−p)','70p−20 = 100−115p'],['精确阈值','p*=120/185=24/37≈0.64864865','p=0.7 选甲；p=0.6 选乙']],takeaway='临界附近保留足够精度；不能把 0.65 当作精确切换点。',notes='在0.649应选甲；若用0.65比较会误判。通常先算精确值再格式化显示。')
add('期望一样，为什么仍会选择不同？',pages='§5，p.75—77',items=[['方案 A：确定获得','5 万元，概率 100%\nEMV = 5 万元'],['方案 B：承担波动','50% 获得 20 万元\n50% 损失 10 万元\nEMV 也为 5 万元']],takeaway='“哪一个更好”还取决于决策者如何评价结果。',notes='先匿名投票，再讨论资金承受能力与风险态度。数学上的期望效用与现实可行约束相辅相成，不能用偏好覆盖不可承受的破产风险。')
chart('效用曲线：给结果一把新的尺',[{'name':name,'points':[[x, (x+10)/30 if k==0 else -math.expm1(-k*(x+10)/30)/(-math.expm1(-k))] for x in range(-10,21)]} for name,k in [('厌恶风险',3),('中性',0),('偏好风险',-3)]], '净结果 / 万元','规范化效用 u(x)',[['凹曲线','边际效用递减，偏向确定结果'],['凸曲线','边际效用递增，更偏向波动']],pages='§5，p.76—77',takeaway='三条曲线端点均为 u(−10)=0、u(20)=1；只在此结果域内比较。',notes='网页采用光滑指数族演示，不宣称它是学生真实效用。教材另有渴望型：拐点前后曲率改变，不能简单归为全局凹或凸。')
add('期望效用：先变换，再加权','equations',pages='§5，p.79—82',items=[['评价有风险的方案','EU(a)=Σ p(θ)u(V(a,θ))','先把每个结果转换为效用，再求期望'],['与“期望的效用”不同','凹效用下：E[u(V)] ≤ u(E[V])','确定等价 CE 满足 u(CE)=E[u(V)]']],takeaway='风险溢价 = EMV−CE；凹效用下非负，线性效用下为 0。',notes='u必须在所有结果上定义且严格递增才有唯一逆函数。数值平移缩放不改变期望效用排序，但任意非线性变换一般会改变。')
add('C3-E4：拖动风险态度','activity',items=[['保持客观概率','比较确定 5 万与 50% 的 20 / −10 万；两者 EMV 始终为 5。'],['改变主观评价','从厌恶风险切到中性、偏好风险，观察曲线、EU 和 CE。'],['解释不等式','厌恶风险时，为什么风险方案的 CE 小于 5 万？']],takeaway='效用不是概率；不要通过改概率来假装偏好发生了变化。',notes='网页曲率k在−5…5。k>0凹，k=0线性，k<0凸。CE用稳定的log1p/expm1计算，避免k接近0时数值相消。')
add('怎样“问”出一条效用曲线？','flow',pages='§5，例 3-13，p.77—79',steps=['固定端点','给出混合赌局','寻找无差异','增加内点'],details=['u(最好)=1\nu(最坏)=0','p 得最好\n1−p 得最坏','确定金额 x 与赌局等价','得到 u(x)=p\n检验一致性'],takeaway='测量的是这个人、这个情境下的偏好，不是所有人的统一心理刻度。',notes='教材的N–M心理实验法亦称标准测定。可二分调整确定金额来接近无差异，再换概率得到更多点；避免诱导学生或声称一次作答即精确测出。')
