add('M3：把 M2 升级成有条件的策略','project',items=[['概率与损益','至少两个状态、两个行动；说明概率依据与净现值口径。'],['信息与风险','画决策树，加入一项调查；计算后验、EVSI、费用与净改善。'],['边界与建议','给出概率切换区间、风险承受约束和效用比较；写出条件策略。']],takeaway='正文 2 页 + 可复算附件 + 3 分钟讲解；案例可用咖啡店或本组真实项目。',notes='若复用M2，先为每个状态分别生成逐年现金流再折现，得到状态条件NPV。不能给同一确定NPV随意贴概率；真实数据需标来源与局限。')
add('翻转课堂：让同学来改变你的结论','activity',items=[['课前准备','每组认领：期望与亏损、树的信息顺序、贝叶斯、效用中的一个。'],['课内讲解','先让听众预测，展示模型，再改变一项关键参数。'],['同伴质询','要求解释结论翻转的原因，并用独立算式复核一个结果。']],takeaway='评分：模型与时序 30%、计算核验 30%、风险解释 25%、表达协作 15%。',notes='第四课留25分钟，全班分区并行讲解，教师抽查；个人退出题另计掌握情况。允许vibe coding，但须保存假设、测试和一处人工纠错记录。')
add('最后检查：你的建议站得住吗？','activity',items=[['数学检查','概率和为 1；后验可复算；0 ≤ EVSI ≤ EVPI；费用只扣一次。'],['行为检查','每个行动只用当时已知信息；风险约束先于最优排名。'],['解释检查','能说明为什么选它、在哪些参数下改变、还缺什么证据。']],takeaway='下一章：如果连可信概率也缺少，我们还能怎样比较方案？',notes='核心主讲共53页。让学生用一句条件句而非一个方案名称交卷，并保留不确定的地方。')
